<?php

namespace App\Modules\Pws\Services;

use App\Modules\Pjk\Contracts\GatewayException;
use App\Modules\Pjk\Contracts\PaymentGateway;
use App\Modules\Pws\Models\KlienApi;
use App\Modules\Pws\Models\SesiBayaran;
use Illuminate\Support\Facades\Validator;
use Illuminate\Validation\Rule;
use Illuminate\Validation\ValidationException;
use Symfony\Component\HttpKernel\Exception\HttpException;

/**
 * SRS-PWS-10..16: online payments by the public, reusing MOD-PJK:
 *  - the AMOUNT is generated by SISDATA (PJK's outstanding ledger balance for
 *    the contract) — the portal can only name the contract and channel;
 *  - the payer enters card / bank details on the gateway page only — nothing
 *    of it passes through SISDATA or the portal (PCI-DSS, SRS-PWS-16);
 *  - status becomes "berjaya" ONLY on server-side confirmation: the
 *    gateway's signed webhook to PJK (which credits the ledger and issues the
 *    receipt) or a server-side status query via PaymentGateway — never the
 *    browser redirect (SRS-PWS-12).
 */
class BayaranService
{
    public function __construct(private InternalApi $api, private AkaunIntegrasi $accounts, private PaymentGateway $gateway) {}

    /** @param array<string, mixed> $input */
    public function initiate(array $input, KlienApi $klien, string $idempotencyKey, string $endUserIp): SesiBayaran
    {
        $data = Validator::make($input, [
            'no_kontrak' => ['required', 'string', 'max:40'],
            'saluran' => ['required', Rule::in($this->gateway->channels())],
            'nama_pembayar' => ['nullable', 'string', 'max:200'],
            'emel_pembayar' => ['nullable', 'email', 'max:150'],
        ], [], ['no_kontrak' => 'no. perjanjian', 'saluran' => 'saluran bayaran', 'emel_pembayar' => 'e-mel pembayar'])->validate();

        // The portal can't pass an amount or charge list: PJK computes the balance.
        $res = $this->api->call('POST', 'pjk/portal/bayaran', array_filter([
            'no_kontrak' => $data['no_kontrak'], 'saluran' => $data['saluran'],
            'nama_pembayar' => $data['nama_pembayar'] ?? null, 'emel_pembayar' => $data['emel_pembayar'] ?? null,
        ], fn ($v) => $v !== null), $this->accounts->portal(), ['Idempotency-Key' => 'pws:'.$klien->id.':'.$idempotencyKey], $endUserIp, [], $data['no_kontrak']);

        if ($res['status'] === 404) {
            throw ValidationException::withMessages(['no_kontrak' => [__('pws::pws.ralat.kontrak_tiada')]]);
        }
        if ($res['status'] === 422) {
            $errors = (array) ($res['body']['errors'] ?? []);
            throw ValidationException::withMessages($errors !== [] ? array_map(fn ($m) => array_values(array_map('strval', (array) $m)), $errors) : ['no_kontrak' => [(string) ($res['body']['message'] ?? '')]]);
        }
        if (! in_array($res['status'], [200, 201], true) || ! isset($res['body']['data']['no_rujukan'])) {
            throw new HttpException(503, __('pws::pws.ralat.gateway_tiada'));
        }
        $tx = (array) $res['body']['data'];

        return SesiBayaran::query()->firstOrCreate(['no_rujukan' => (string) $tx['no_rujukan']], [
            'no_kontrak' => $data['no_kontrak'], 'klien_id' => $klien->id, 'jumlah' => (string) $tx['amaun'], 'mata_wang' => 'MYR',
            'saluran_bayaran' => $data['saluran'], 'url_bayaran' => $this->publicUrl($tx), 'status' => 'menunggu', 'cap_masa_mula' => now(),
        ]);
    }

    /** Server-side status query (never the redirect). */
    public function refresh(SesiBayaran $sesi): SesiBayaran
    {
        if (in_array($sesi->status, SesiBayaran::AKHIR, true)) {
            return $sesi;
        }
        try {
            $q = $this->gateway->query($sesi->no_rujukan);
        } catch (GatewayException) {
            return $sesi; // gateway down: keep "menunggu", PJK's poller resolves it later
        }
        if ($q === null) {
            return $sesi;
        }
        $status = match ($q['status']) {
            'berjaya' => 'berjaya', 'gagal' => 'gagal', 'dibatalkan' => 'dibatalkan', 'tamat_masa' => 'tamat_tempoh', default => 'menunggu',
        };
        // Never mark success for an amount other than the one SISDATA generated.
        if ($status === 'berjaya' && $q['amaun'] !== null && bccomp((string) $q['amaun'], (string) $sesi->jumlah, 2) !== 0) {
            $status = 'menunggu';
        }
        $sesi->forceFill([
            'status' => $status, 'rujukan_gateway' => $q['rujukan_gateway'] ?? $sesi->rujukan_gateway,
            'cap_masa_pengesahan' => in_array($status, SesiBayaran::AKHIR, true) ? now() : null,
            'disahkan_melalui' => in_array($status, SesiBayaran::AKHIR, true) ? 'pertanyaan_status' : null,
        ])->save();

        return $sesi;
    }

    /** @return array<string, mixed> */
    public static function present(SesiBayaran $s): array
    {
        return [
            'no_rujukan' => $s->no_rujukan, 'no_kontrak' => $s->no_kontrak, 'jumlah' => (string) $s->jumlah, 'mata_wang' => $s->mata_wang,
            'saluran' => $s->saluran_bayaran, 'status' => $s->status, 'status_nama' => __('pws::pws.status_bayaran.'.$s->status),
            'url_bayaran' => in_array($s->status, SesiBayaran::AKHIR, true) ? null : $s->url_bayaran,
            'dimulakan' => $s->cap_masa_mula?->toIso8601String(), 'disahkan' => $s->cap_masa_pengesahan?->toIso8601String(),
        ];
    }

    /**
     * The mock gateway's page is an internal SISDATA screen; the portal shows
     * its own test-gateway page instead (non-production only).
     *
     * @param  array<string, mixed>  $tx
     */
    private function publicUrl(array $tx): ?string
    {
        $url = isset($tx['url_bayaran']) ? (string) $tx['url_bayaran'] : null;
        if ($url !== null && str_starts_with($url, '/admin/')) {
            return config('pws.gateway_ujian') ? 'ujian:'.$tx['no_rujukan'] : null;
        }

        return $url;
    }
}
